import re, json
from tasks import TASKS
def first_block(reply):
    m=re.search(r'```(?:python|py)?\s*\n(.*?)```', reply, re.DOTALL)
    return m.group(1) if m else reply
def first_py_block(reply):
    # first fenced block that does NOT specify a non-python language (c/java/...)
    for mm in re.finditer(r'```([a-zA-Z0-9_+-]*)\s*\n(.*?)```', reply, re.DOTALL):
        lang=mm.group(1).lower(); body=mm.group(2)
        if lang in ('','python','py'):
            return body, lang
    return None, None
def grade1(reply, test):
    b,_=first_py_block(reply)
    if b is None: return False,'no python block'
    ns={}
    try: exec(b, ns)
    except Exception as e: return False,f'exec {type(e).__name__}: {e}'
    try: exec(test, ns)
    except Exception as e: return False,f'test {type(e).__name__}: {e}'
    return True,'ok'
for fn in ['gen/1.json','gen/2.json']:
    d=json.load(open(fn))
    off = 0 if fn=='gen/1.json' else 16
    n=0; fails=[]
    for i,it in enumerate(d):
        ok,msg=grade1(it['reply'], TASKS[off+i][1])
        n+=ok
        if not ok: fails.append((off+i,msg))
    print(fn, f'{n}/{len(d)}', fails)

